// Find TowerB(9)'s RaySearch and re-run with the actual player position
var tower = GameObject.Find("TowerB (9)");
if (tower == null) return "TowerB (9) not found";
var edgeSearch = tower.transform.Find("EdgeSearch");
if (edgeSearch == null) return "EdgeSearch not found";
var rs = edgeSearch.GetComponent<RaySearch>();
if (rs == null) return "RaySearch not found";

// Player is at approx (-152, 19, 164). Tower center at (-84, ~24, 137).
// Simulate WallMerge: ray from a point near the tower outward face, towards tower center.
Vector3 origin = new Vector3(-84.12f, 25.5f, 146.5f); // close to first corner
Vector3 toCenter = (tower.transform.position - origin); toCenter.y = 0; toCenter.Normalize();

rs.mergeMode = WallMerge.WallMergeMode.Current;
rs.DoPointsFromPlayer(origin, toCenter);

var sb = new System.Text.StringBuilder();
sb.AppendLine($"TowerB (9) -> meshPoints={rs.meshPoints.Count}, cornerPoints={rs.cornerPoints.Count}, IsClosedLoop={rs.IsClosedLoop}");
sb.AppendLine($"stepSize={rs.stepSize}, checkCountMax={rs.checkCountMax}");

// Also verify the new GetPivotPosition algorithm on every corner
int N = rs.cornerPoints.Count;
float distanceToTurn = 1f;
int bad = 0;
for (int i = 0; i < N; i++)
{
    Vector3 cur = rs.cornerPoints[i].position;
    int prev = rs.IsClosedLoop ? (i - 1 + N) % N : Mathf.Max(i - 1, 0);
    int next = rs.IsClosedLoop ? (i + 1) % N : Mathf.Min(i + 1, N - 1);
    Vector3 nFrom = rs.cornerPoints[prev].normal;
    Vector3 nTo = rs.cornerPoints[next].normal;
    Vector3 outward = (nFrom + nTo);
    Vector3 inward = (outward.sqrMagnitude < 0.0001f) ? -nFrom : -outward.normalized;
    Vector3 pivot = cur + inward * distanceToTurn;
    float dist = Vector3.Distance(pivot, cur);
    if (dist > 5f || float.IsNaN(pivot.x)) { bad++; sb.AppendLine($"  [BAD {i}] dist={dist:F2}"); }
}
sb.AppendLine($"bad pivots: {bad}/{N}");
return sb.ToString();
